142	  factory Plugin._fromLegacyYaml(
143	    String name,
144	    String path,
145	    dynamic pluginYaml,
146	    List<String> dependencies,
147	  ) {
148	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
149	    final String pluginClass = pluginYaml['pluginClass'] as String;
150	    if (pluginYaml != null && pluginClass != null) {
151	      final String androidPackage = pluginYaml['androidPackage'] as String;
152	      if (androidPackage != null) {
153	        platforms[AndroidPlugin.kConfigKey] = AndroidPlugin(
154	          name: name,
155	          package: pluginYaml['androidPackage'] as String,
156	          pluginClass: pluginClass,
157	          pluginPath: path,
158	        );
159	      }
160	
161	      final String iosPrefix = pluginYaml['iosPrefix'] as String ?? '';
162	      platforms[IOSPlugin.kConfigKey] =
163	          IOSPlugin(
164	            name: name,
165	            classPrefix: iosPrefix,
166	            pluginClass: pluginClass,
167	          );
168	    }
169	    return Plugin(
170	      name: name,
171	      path: path,
172	      platforms: platforms,
173	      dependencies: dependencies,
174	    );
175	  }
