181	      'iosPrefix',
182	      'pluginClass',
183	    }.any(yaml.containsKey);
184	
185	    final bool usesNewPluginFormat = yaml.containsKey('platforms');
186	
187	    if (usesOldPluginFormat && usesNewPluginFormat) {
188	      const String errorMessage =
189	          'The flutter.plugin.platforms key cannot be used in combination with the old '
190	          'flutter.plugin.{androidPackage,iosPrefix,pluginClass} keys. '
191	          'See: https://flutter.dev/docs/development/packages-and-plugins/developing-packages#plugin';
192	      return <String>[errorMessage];
193	    }
194	
195	    if (usesNewPluginFormat) {
196	      return _validateMultiPlatformYaml(yaml['platforms'] as YamlMap);
197	    } else {
198	      return _validateLegacyYaml(yaml);
199	    }
200	  }
